mapper.select:
/* ConsentMapper.countTermsExists */
SELECT COUNT(1)
FROM TB_TERMS B
WHERE B.TERMS_ID = #{termsId}

/* ConsentMapper.selectUserSiteCd */
SELECT A.SITE_CD
FROM (
    SELECT U.SITE_CD AS SITE_CD, 1 AS SRC_ORD   
    FROM TB_USER U
    WHERE U.CMPNY_CD = #{cmpnyCd}
      AND U.USER_CD = #{userCd}
      AND IFNULL(U.USE_YN, 'N') = 'Y'
    UNION ALL
    SELECT D.SITE_CD AS SITE_CD, 2 AS SRC_ORD
    FROM TB_DAILY_USER D
    WHERE D.CMPNY_CD = #{cmpnyCd}
      AND D.USER_CD = #{userCd}
      AND IFNULL(D.USE_YN, 'N') = 'Y'
) A
WHERE A.SITE_CD IS NOT NULL

ORDER BY A.SRC_ORD ASC
LIMIT 1

/* ConsentMapper.selectUserAgrYn */
SELECT IFNULL(A.AGR_YN, 'N')
FROM TB_TERMS_USER_AGR_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.TERMS_ID = #{termsId}
  AND A.TERMS_VERSION = #{termsVersion}
LIMIT 1

/* ConsentMapper.selectUserAgrYnForUpdate */
SELECT IFNULL(A.AGR_YN, 'N')
FROM TB_TERMS_USER_AGR_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.TERMS_ID = #{termsId}
  AND A.TERMS_VERSION = #{termsVersion}
FOR UPDATE

/* ConsentMapper.selectUserAgrState */
SELECT IFNULL(A.AGR_YN, 'N') AS agrYn
     , A.CONSENT_STATE       AS consentState
FROM TB_TERMS_USER_AGR_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.TERMS_ID = #{termsId}
  AND A.TERMS_VERSION = #{termsVersion}
LIMIT 1

/* ConsentMapper.selectUserAgrStateForUpdate */
SELECT IFNULL(A.AGR_YN, 'N') AS agrYn
     , A.CONSENT_STATE       AS consentState
FROM TB_TERMS_USER_AGR_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.TERMS_ID = #{termsId}
  AND A.TERMS_VERSION = #{termsVersion}
FOR UPDATE

/* ConsentMapper.countAgreedAnyVersion */
SELECT COUNT(1)
FROM TB_TERMS_USER_AGR_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.TERMS_ID = #{termsId}
  AND IFNULL(A.AGR_YN, 'N') = 'Y'

/* ConsentMapper.selectConsentedUserCds */
SELECT A.USER_CD
FROM TB_TERMS_USER_AGR_MGMT A
     INNER JOIN TB_TERMS T
        ON (
            T.TERMS_ID = A.TERMS_ID
        AND T.TERMS_VERSION = A.TERMS_VERSION
        )
WHERE 1=1
  AND A.CMPNY_CD = #{cmpnyCd}
  AND A.TERMS_ID = #{termsId}
  AND IFNULL(A.AGR_YN, 'N') = 'Y'
  AND T.USE_YN = 'Y'
  AND A.USER_CD IN
  #{u}

/* ConsentMapper.selectTermsCurrentVersion */
SELECT B.TERMS_VERSION
FROM TB_TERMS B
WHERE B.TERMS_ID = #{termsId}
  AND B.USE_YN = 'Y'
LIMIT 1

mapper.insert:
/* ConsentMapper.upsertTermsAgr */
INSERT INTO TB_TERMS_USER_AGR_MGMT (
      CMPNY_CD
    , USER_CD
    , TERMS_ID
    , TERMS_VERSION
    , AGR_YN
    , CONSENT_STATE
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{userCd}
    , #{termsId}
    , #{termsVersion}
    , #{agrYn}
    , #{consentState}
    , #{userCd}
    , NOW()
)
ON DUPLICATE KEY UPDATE
      AGR_YN = VALUES(AGR_YN)
    /* 위치정보 S2: consentState 가 null 이면(상태 관리 대상 아닌 약관) 기존 값을 보존한다.
       NULL 을 그대로 덮으면 다른 경로의 저장 한 번으로 005 상태가 지워진다. */
    , CONSENT_STATE = COALESCE(VALUES(CONSENT_STATE), CONSENT_STATE)

/* ConsentMapper.insertTermsAgrHist */
INSERT INTO TB_TERMS_USER_AGR_HIST (
      CMPNY_CD
    , USER_CD
    , TERMS_ID
    , TERMS_VERSION
    , BEFORE_AGR_YN
    , AFTER_AGR_YN
    , BEFORE_STATE
    , AFTER_STATE
    , AGR_SOURCE
    , ACTOR_CMPNY_CD
    , ACTOR_USER_CD
    , ACTION_DTIME
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{userCd}
    , #{termsId}
    , #{termsVersion}
    , #{beforeAgrYn}
    , #{afterAgrYn}
    , #{beforeState}
    , #{afterState}
    , #{agrSource}
    , #{actorCmpnyCd}
    , #{actorUserCd}
    , NOW()
    , #{actorUserCd}
    , NOW()
)
